12→$sourceTreeState = if ([string]::IsNullOrWhiteSpace((git status --porcelain))) { "clean" } else { "dirty" }
13→$xlcallCatalogPath = "docs/function-lane/XLCALL_CODE_CATALOG.csv"
14→$xlcallByStableId = @{}
15→if (Test-Path $xlcallCatalogPath) {
16→    Import-Csv $xlcallCatalogPath |
17→        Where-Object {
18→            $_.xlcall_category -eq "built_in_function" -and
19→            $_.oxfunc_match_status -eq "matched_current_catalog" -and
20→            -not [string]::IsNullOrWhiteSpace($_.oxfunc_surface_stable_id)
21→        } |
22→        ForEach-Object {
23→            $xlcallByStableId[$_.oxfunc_surface_stable_id] = $_
24→        }
25→}
