27→$metaPattern = 'function_id:\s*"(?<id>[^"]+)"[\s\S]*?arity:\s*(?:Arity::exact\((?<exact>\d+)\)|Arity\s*\{\s*min:\s*(?<min>\d+),\s*max:\s*(?<max>\d+)\s*\})[\s\S]*?determinism:\s*DeterminismClass::(?<det>\w+)[\s\S]*?volatility:\s*VolatilityClass::(?<vol>\w+)[\s\S]*?host_interaction:\s*HostInteractionClass::(?<host>\w+)[\s\S]*?thread_safety:\s*ThreadSafetyClass::(?<thread>\w+)[\s\S]*?arg_preparation_profile:\s*ArgPreparationProfile::(?<arg>\w+)[\s\S]*?coercion_lift_profile:\s*CoercionLiftProfile::(?<coercion>\w+)[\s\S]*?kernel_signature_class:\s*KernelSignatureClass::(?<kernel>\w+)[\s\S]*?fec_dependency_profile:\s*FecDependencyProfile::(?<fec>\w+)[\s\S]*?surface_fec_dependency_profile:\s*FecDependencyProfile::(?<surface>\w+)'
28→$reshapeMetaPattern = 'pub const \w+_META:\s*FunctionMeta\s*=\s*reshape_meta!\("(?<id>[^"]+)",\s*(?<min>\d+),\s*(?<max>\d+)\);'
29→
30→$metaById = @{}
31→Get-ChildItem "crates/oxfunc_core/src/functions" -Filter *.rs | ForEach-Object {
32→    $text = Get-Content $_.FullName -Raw
33→    foreach ($m in [regex]::Matches($text, $metaPattern)) {
34→        $arityMin = if ($m.Groups['exact'].Success) { $m.Groups['exact'].Value } else { $m.Groups['min'].Value }
35→        $arityMax = if ($m.Groups['exact'].Success) { $m.Groups['exact'].Value } else { $m.Groups['max'].Value }
36→        $metaById[$m.Groups['id'].Value] = [ordered]@{
37→            arity_min = $arityMin
38→            arity_max = $arityMax
39→            arg_preparation_profile = $m.Groups['arg'].Value
40→            coercion_lift_profile = $m.Groups['coercion'].Value
41→            kernel_signature_class = $m.Groups['kernel'].Value
42→            determinism_class = $m.Groups['det'].Value
43→            volatility_class = $m.Groups['vol'].Value
44→            host_interaction_class = $m.Groups['host'].Value
45→            thread_safety_class = $m.Groups['thread'].Value
46→            fec_dependency_profile = $m.Groups['fec'].Value
47→            surface_fec_dependency_profile = $m.Groups['surface'].Value
48→            metadata_status = "function_meta_extracted"
49→        }
50→    }
51→    foreach ($m in [regex]::Matches($text, $reshapeMetaPattern)) {
52→        if (-not $metaById.ContainsKey($m.Groups['id'].Value)) {
53→            $metaById[$m.Groups['id'].Value] = [ordered]@{
54→                arity_min = $m.Groups['min'].Value
55→                arity_max = $m.Groups['max'].Value
56→                arg_preparation_profile = "ValuesOnlyPreAdapter"
57→                coercion_lift_profile = "Custom"
58→                kernel_signature_class = "Custom"
59→                determinism_class = "Deterministic"
60→                volatility_class = "NonVolatile"
61→                host_interaction_class = "None"
62→                thread_safety_class = "SafePure"
63→                fec_dependency_profile = "None"
64→                surface_fec_dependency_profile = "RefOnly"
65→                metadata_status = "function_meta_extracted"
66→            }
67→        }
68→    }
69→}
